<?php
namespace Tests\Feature;use Tests\TestCase;use Illuminate\Foundation\Testing\RefreshDatabase;use App\Models\{User,Role,PortfolioCategory,PortfolioItem,PortfolioMedia};use Illuminate\Support\Facades\Hash;
class PortfolioTest extends TestCase{use RefreshDatabase;private function admin(){ $u=User::create(['name'=>'Admin','phone'=>'+201'.random_int(100000000,999999999),'password_hash'=>Hash::make('Password1'),'status'=>'ACTIVE']);$u->roles()->attach(Role::firstOrCreate(['name'=>'ADMIN']));return $u;}protected function setUp():void{parent::setUp();$this->artisan('migrate');PortfolioCategory::create(['name'=>'Training Success','status'=>'ACTIVE']);}
public function test_public_active_portfolio():void{$a=$this->admin();PortfolioItem::create(['category_id'=>1,'title'=>'Case','short_description'=>'Short','description'=>'Long','status'=>'ACTIVE','created_by'=>$a->id]);$this->getJson('/api/v1/portfolio')->assertOk()->assertJsonCount(1,'data.data');}
public function test_inactive_hidden():void{$a=$this->admin();PortfolioItem::create(['category_id'=>1,'title'=>'Hidden','short_description'=>'Short','description'=>'Long','status'=>'INACTIVE','created_by'=>$a->id]);$this->getJson('/api/v1/portfolio')->assertOk()->assertJsonCount(0,'data.data');}
public function test_admin_crud_and_media_relationship():void{$a=$this->admin();$r=$this->actingAs($a,'api')->postJson('/api/v1/admin/portfolio',['category_id'=>1,'title'=>'Case','short_description'=>'Short','description'=>'Long']);$r->assertCreated();$id=$r->json('data.id');PortfolioMedia::create(['portfolio_id'=>$id,'file_url'=>'https://example.com/a.jpg','type'=>'IMAGE']);$this->assertCount(1,PortfolioItem::find($id)->media);$this->actingAs($a,'api')->putJson("/api/v1/admin/portfolio/$id",['title'=>'Updated'])->assertOk();$this->actingAs($a,'api')->deleteJson("/api/v1/admin/portfolio/$id")->assertNoContent();}
public function test_unauthorized_cannot_manage():void{$this->postJson('/api/v1/admin/portfolio',[])->assertUnauthorized();}
public function test_filtering_works():void{$a=$this->admin();PortfolioItem::create(['category_id'=>1,'title'=>'Training Case','short_description'=>'Short','description'=>'Long','status'=>'ACTIVE','created_by'=>$a->id]);$this->getJson('/api/v1/portfolio?search=training&category_id=1')->assertOk()->assertJsonCount(1,'data.data');}}
